/**
 * Migration runner — `bun --filter @wirewatch/db run migrate`.
 *
 * Migrations are expand-only (ADR-0004): generated by drizzle-kit,
 * committed to git, applied by CI and as a Railway deploy command.
 */
import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import { createDb, resolveDatabaseUrl } from "./client";

const url = resolveDatabaseUrl();
const { db, sql } = createDb(url);

console.log(`[db] applying migrations from packages/db/drizzle …`);
await migrate(db, {
  migrationsFolder: fileURLToPath(new URL("../drizzle", import.meta.url)),
});
console.log(`[db] migrations applied`);

await sql.end();
